//! Golden DTOs captured from the frozen Python baseline using the 78 existing
//! parser, Usage-contract and automatic-skill-load tests. All inputs are synthetic;
//! temporary prefixes are normalized. No interpreter is needed to execute this test.
use base64::{engine::general_purpose::STANDARD, Engine};
use localbrain_core::backend::ingest::parse_session;
use serde_json::{json, Value};
use std::{fs, path::Path};

#[test]
fn provider_dtos_match_frozen_parser_usage_and_skill_fixtures() {
    let fixtures: Vec<Value> = serde_json::from_str(CASES).unwrap();
    assert_eq!(fixtures.len(), 156);
    let temp = tempfile::Builder::new()
        .prefix("lb-native-ingest-fixtures-")
        .tempdir()
        .unwrap();
    for (index, fixture) in fixtures.into_iter().enumerate() {
        let path = temp
            .path()
            .join(fixture["path"].as_str().unwrap().trim_start_matches('/'));
        fs::create_dir_all(path.parent().unwrap()).unwrap();
        fs::write(
            &path,
            STANDARD.decode(fixture["bytes"].as_str().unwrap()).unwrap(),
        )
        .unwrap();
        let root = path
            .ancestors()
            .skip(1)
            .find(|p| {
                p.file_name()
                    .and_then(|s| s.to_str())
                    .is_some_and(|s| ["sessions", "archived_sessions"].contains(&s))
            })
            .and_then(Path::parent)
            .unwrap_or(path.parent().unwrap());
        if let Some(config) = fixture["config"].as_str() {
            fs::write(root.join("config.toml"), STANDARD.decode(config).unwrap()).unwrap();
        } else {
            let _ = fs::remove_file(root.join("config.toml"));
        }
        let parsed = parse_session(fixture["provider"].as_str().unwrap(), &path)
            .unwrap_or_else(|e| panic!("fixture {index} {}: {e}", fixture["case"]))
            .unwrap();
        let mut expected = fixture["expected"].clone();
        expected["source_path"] = json!(path);
        assert_eq!(
            serde_json::to_value(parsed).unwrap(),
            expected,
            "fixture {index}: {}",
            fixture["case"]
        );
    }
}

