#[test]
fn ignored_python_json_scalars_preserve_valid_messages_and_selected_failures_stay_explicit() {
    let temp = tempfile::tempdir().unwrap();
    for provider in ["claude", "codex"] {
        for (index, scalar) in ["NaN", "Infinity", "-Infinity", "1e999", r#""\ud800""#]
            .iter()
            .enumerate()
        {
            let path = temp.path().join(format!("{provider}-{index}.jsonl"));
            let text = if provider == "claude" {
                format!(
                    r#"{{"type":"user","sessionId":"scalar-session","ignored":{{"nested":{scalar}}},"message":"Valid 한글 message"}}"#
                )
            } else {
                format!(
                    r#"{{"type":"event_msg","ignored":{{"nested":{scalar}}},"payload":{{"type":"user_message","message":"Valid 한글 message"}}}}"#
                )
            };
            fs::write(&path, text).unwrap();
            let parsed = parse_session(provider, &path).unwrap().unwrap();
            assert_eq!(parsed.events.len(), 1, "{provider} {scalar}");
            assert_eq!(parsed.events[0].text.as_deref(), Some("Valid 한글 message"));
            assert_eq!(parsed.skipped_lines, 0);
        }
        let path = temp.path().join(format!("{provider}-selected.jsonl"));
        let text = if provider == "claude" {
            r#"{"type":"user","message":"bad \ud800 text"}"#
        } else {
            r#"{"type":"event_msg","payload":{"type":"user_message","message":"bad \ud800 text"}}"#
        };
        fs::write(&path, text).unwrap();
        assert_eq!(
            parse_session(provider, &path).unwrap_err().code,
            "source_unicode"
        );
    }
}
#[test]
fn arbitrary_usage_integers_and_nonfinite_components_keep_types_without_invalid_output_json() {
    let temp = tempfile::tempdir().unwrap();
    let path = temp.path().join("usage.jsonl");
    fs::write(&path,r#"{"type":"assistant","sessionId":"usage","message":{"id":"big","model":"claude-sonnet-4-20250514","content":[{"type":"text","text":"answer"}],"usage":{"input_tokens":1267650600228229401496703205376,"output_tokens":2}}}
{"type":"assistant","sessionId":"usage","message":{"id":"nan","model":"claude-sonnet-4-20250514","usage":{"input_tokens":NaN,"output_tokens":2}}}
"#).unwrap();
    let parsed = parse_session("claude", &path).unwrap().unwrap();
    assert_eq!(parsed.usage_records.len(), 2);
    assert_eq!(
        parsed.usage_records[0]
            .input_tokens
            .as_ref()
            .unwrap()
            .to_string(),
        "1267650600228229401496703205376"
    );
    assert_eq!(
        parsed.usage_records[0]
            .total_tokens
            .as_ref()
            .unwrap()
            .to_string(),
        "1267650600228229401496703205378"
    );
    assert_eq!(parsed.usage_records[1].capability_state, "malformed");
    assert!(parsed.usage_records[1].input_tokens.is_none());
    let encoded = serde_json::to_string(&parsed).unwrap();
    assert!(serde_json::from_str::<Value>(&encoded).is_ok());
}
#[test]
fn zstd_stream_and_plain_file_preserve_decompressed_lines_and_native_identity() {
    let temp = tempfile::tempdir().unwrap();
    let plain = temp.path().join("rollout.jsonl");
    let compressed = temp.path().join("rollout.jsonl.zst");
    let input=b"{\"type\":\"session_meta\",\"payload\":{\"id\":\"same-native-session\"}}\r\nnot-json\r\n{\"type\":\"event_msg\",\"payload\":{\"type\":\"user_message\",\"message\":\"hello\"}}\n";
    fs::write(&plain, input).unwrap();
    fs::write(
        &compressed,
        zstd::stream::encode_all(input.as_slice(), 3).unwrap(),
    )
    .unwrap();
    let a = parse_session("codex", &plain).unwrap().unwrap();
    let b = parse_session("codex", &compressed).unwrap().unwrap();
    assert_eq!(a.events, b.events);
    assert_eq!(a.external_id, b.external_id);
    assert_eq!(a.skipped_lines, 1);
    assert_eq!(b.events[0].source_line, 3);
}

#[test]
fn python_whitespace_casefold_and_longest_skill_alias_preserve_source_meaning() {
    let temp = tempfile::tempdir().unwrap();
    let path = temp.path().join("skills.jsonl");
    let records = [
        json!({"type":"user","uuid":"request","message":"a\u{1c}b"}),
        json!({"type":"assistant","message":{"content":[{"type":"tool_use","name":"Skill","id":"short","input":{"skill":"foo"}},{"type":"tool_use","name":"Skill","id":"long","input":{"skill":"foo bar"}},{"type":"tool_use","name":"Skill","id":"unicode","input":{"skill":"Straße"}}]}}),
        json!({"type":"user","uuid":"mention","message":"Use foo bar and STRASSE"}),
    ];
    fs::write(
        &path,
        records
            .iter()
            .map(Value::to_string)
            .collect::<Vec<_>>()
            .join("\n"),
    )
    .unwrap();
    let parsed = parse_session("claude", &path).unwrap().unwrap();
    assert_eq!(parsed.title, "a b");
    let mentioned = parsed
        .skill_observations
        .iter()
        .filter(|o| o.signal_kind == "claude_skill_mention" && o.source_line == 3)
        .map(|o| o.skill_name.as_str())
        .collect::<Vec<_>>();
    assert_eq!(mentioned, vec!["Straße", "foo bar"]);
}

#[test]
fn approved_nested_request_hints_keep_original_depth_first_field_order() {
    let temp = tempfile::tempdir().unwrap();
    let path = temp.path().join("ordered-hints.jsonl");
    let records = [
        json!({"type":"session_meta","payload":{"id":"ordered"}}),
        json!({"type":"response_item","payload":{"type":"function_call","name":"mcp_gateway.gateway_dispatch","call_id":"read","arguments":{"capability":"jira__searchIssuesByJql","params":{"key":"EARLY-1"},"url":"https://example.test/browse/LATE-2"}}}),
        json!({"type":"response_item","payload":{"type":"function_call_output","call_id":"read","output":{"success":false}}}),
    ];
    fs::write(
        &path,
        records
            .iter()
            .map(Value::to_string)
            .collect::<Vec<_>>()
            .join("\n"),
    )
    .unwrap();
    let parsed = parse_session("codex", &path).unwrap().unwrap();
    let refs = parsed
        .reference_candidates
        .iter()
        .map(|r| {
            (
                r.reference_kind.as_str(),
                r.reference.as_str(),
                r.evidence_ordinal,
            )
        })
        .collect::<Vec<_>>();
    assert_eq!(
        refs,
        vec![
            ("jira_key", "EARLY-1", 1),
            ("url", "https://example.test/browse/LATE-2", 2)
        ]
    );
}

#[test]
fn confluence_hint_digits_follow_python_digit_rather_than_numeric_category() {
    let temp = tempfile::tempdir().unwrap();
    let path = temp.path().join("digits.jsonl");
    let records = [
        json!({"type":"response_item","payload":{"type":"function_call","name":"wiki__getPageById","call_id":"digit","arguments":{"pageId":"²"}}}),
        json!({"type":"response_item","payload":{"type":"function_call_output","call_id":"digit","output":{"success":false}}}),
        json!({"type":"response_item","payload":{"type":"function_call","name":"wiki__getPageById","call_id":"numeric","arguments":{"pageId":"Ⅻ"}}}),
        json!({"type":"response_item","payload":{"type":"function_call_output","call_id":"numeric","output":{"success":false}}}),
    ];
    fs::write(
        &path,
        records
            .iter()
            .map(Value::to_string)
            .collect::<Vec<_>>()
            .join("\n"),
    )
    .unwrap();
    let parsed = parse_session("codex", &path).unwrap().unwrap();
    assert_eq!(parsed.reference_candidates.len(), 1);
    assert_eq!(parsed.reference_candidates[0].reference, "²");
}

#[test]
fn codex_config_tier_selection_ignores_unrelated_lossless_toml_scalars() {
    let temp = tempfile::tempdir().unwrap();
    let sessions = temp.path().join("sessions");
    fs::create_dir(&sessions).unwrap();
    fs::write(
        temp.path().join("config.toml"),
        "service_tier='fast'\nunknown_date=2026-01-01\nlarge=1267650600228229401496703205376\n",
    )
    .unwrap();
    let path = sessions.join("rollout.jsonl");
    let records = [
        json!({"type":"session_meta","payload":{"id":"tier"}}),
        json!({"type":"turn_context","payload":{"turn_id":"turn","model":"gpt-5.4"}}),
        json!({"type":"event_msg","timestamp":"2026-11-01T00:00:00Z","payload":{"type":"token_count","info":{"last_token_usage":{"input_tokens":10,"output_tokens":2,"cached_input_tokens":0,"reasoning_output_tokens":1,"total_tokens":12}}}}),
    ];
    fs::write(
        &path,
        records
            .iter()
            .map(Value::to_string)
            .collect::<Vec<_>>()
            .join("\n"),
    )
    .unwrap();
    let parsed = parse_session("codex", &path).unwrap().unwrap();
    assert_eq!(parsed.usage_records[0].capability["service_tier"], "fast");
    assert_eq!(
        parsed.usage_records[0].capability["service_tier_source"],
        "config_fallback"
    );
}
